\label{24marzo2018-2}Let $\omega_0$ be as in \eqref{11marzo2018-6}, let $\omega_1,\dots,\omega_n$ be holomorphic of $(z,u)\in \mathbb{C}\times \mathbb{D}\big(u^0\big)$, and~$A(u)$ holomorphic on $\mathbb{D}\big(u^0\big)$. The integrability condition \eqref{11marzo2018-3} implies that~$A$ satisfies
\begin{gather}\label{23marzo2018-8}
\frac{\partial A}{\partial u_j}=[\omega_j(0,u),A], \qquad j=1,\dots,n,
\end{gather}
and that the above is Frobenius integrable. Moreover, the system
\begin{gather}\label{23marzo2018-7}
{\rm d} G=\left(\sum_{j=1}^n \omega_j(0,u){\rm d} u_j\right) G
\end{gather}
is Frobenius integrable.

ondition \eqref{11marzo2018-3} for $\beta=0$ and $\alpha=j\geq 1$ yields
\begin{gather}\label{24marzo2018-1}
\frac{\partial}{\partial u_j}
\left(\Lambda+\frac{A}{z}\right)+\left(\Lambda+\frac{A}{z}\right)\omega_j(z,u)=\frac{\partial \omega_j(z,u)}{\partial z}
+\omega_j(z,u)\left(\Lambda+\frac{A}{z}\right).
\end{gather}
Since $\omega_j(z,u)=\omega(0,u)+$ Taylor series in $z$, identification of the coefficients of $z^{-1}$ yields \eqref{23marzo2018-8}. The condition~\eqref{11marzo2018-3} for $\beta=i\geq 1$ and $\alpha=j\geq 1$ is regular at $z=0$. In particular, for $z=0$ we have
\begin{gather}\label{24marzo2018-3}
\frac{\partial \omega_i(0,u)}{\partial u_j}+\omega_i(0,u)\omega_j(0,u)=\frac{\partial \omega_j(0,u)}{\partial u_i}+\omega_j(0,u)\omega_i(0,u),\qquad i\neq j=1,\dots,n,
\end{gather}
which is the Frobenius integrability condition for \eqref{23marzo2018-7}. It is also the integrability condition of~\eqref{23marzo2018-8}. Indeed, let us compute (for brevity, we write $\omega_j(0):=\omega_j(0,u)$)
\begin{gather*}
\partial_k[\omega_j(0),A]-\partial_j[\omega_k(0),A]= \bigr(\partial_k\omega_j(0) A+\omega_j(0)\partial_kA-\partial_kA \omega_j(0)-A\partial_k\omega_j(0)\bigr)\\
\qquad\quad{} -\bigl(\partial_j\omega_k(0) A+\omega_k(0)\partial_jA-\partial_jA \omega_k(0)-A\partial_j\omega_k(0)\bigr)\\
\qquad{} =\bigr(\partial_k\omega_j(0) A+\omega_j(0)[\omega_k(0)A-A\omega_k(0)]-[\omega_k(0)A-A\omega_k(0)] \omega_j(0)-A\partial_k\omega_j(0)\bigr)\\
\qquad\quad{} -\bigr(\partial_j\omega_k(0) A+\omega_k(0)[\omega_j(0)A-A\omega_j(0)]-[\omega_j(0)A-A\omega_j(0)] \omega_k(0)-A\partial_j\omega_k(0)\bigr)\\
\qquad{} =\bigl\{[\partial_k\omega_j(0)+\omega_j(0)\omega_k(0)]-[\partial_j\omega_k(0)+\omega_k(0)\omega_j(0)]\bigr\}A\\
\qquad\quad{} + A\bigl\{[\omega_k(0)\omega_j(0)-\partial_k\omega_j(0)]-[\omega_j(0)\omega_k(0)-\partial_j\omega_k(0)]\bigr\}.
\end{gather*}
The last expression is zero for any possible $A$ if and only if~\eqref{24marzo2018-3} holds.

\label{11marzo2018-7}Let $\omega_0$ be as in \eqref{11marzo2018-6}, let $\omega_1,\dots,\omega_n$ be holomorphic of $(z,u)\in \mathbb{C}\times \mathbb{D}\big(u^0\big)$, and $A(u)$ holomorphic on $\mathbb{D}\big(u^0\big)$. Then, $A(u)$ is holomorphically similar to a constant $($i.e., independent of $u)$ Jordan form $J$, namely there exists a holomorphic fundamental matrix $G(u)$ of \eqref{23marzo2018-7} on $\mathbb{D}\big(u^0\big)$, such that
\begin{gather*}
G(u)^{-1}A(u)G(u)=J.
\end{gather*}
In particular, this means that the weak isomonodromy deformation \eqref{11marzo2018-1} is isospectral.

\label{30luglio 2018-3} Let $A(u)$ be holomorphic on $\mathbb{D}\big(u^0\big)$ and $\omega_1(z,u), \dots,\omega_n(z,u)$ be holomorphic on $ \mathbb{C}\times \mathbb{D}\big(u^0\big)$. Then:
 \begin{itemize}\itemsep=0pt
 \item the Pfaffian system \eqref{11marzo2018-2} admits fundamental matrix solutions in Levelt form \eqref{11marzo2018-8}--\eqref{3aprile2018-1};
 \item the exponents $D$ and $L$ are constant;
 \item the convergent series $\eqref{3aprile2018-1}$ defines a holomorphic matrix valued function on $\mathbb{C}\times \mathbb{D}\big(u^0\big)$; equivalently, $Y^{(0)}(z,u)$ is holomorphic on $\mathcal{R}\times \mathcal{U}_\epsilon\big(u^C\big)$.
 \end{itemize}

he Pfaffian system \eqref{11marzo2018-2} is of Fuchsian type at $z=0$. Thus, we can apply the result of \cite{Bolibruch0,YT}. In particular, by theorem 5 of \cite{YT}, there exists a gauge transformation
 \begin{gather} \label{31luglio2018-3}
 Y=V(z,u) \widetilde{Y},
\end{gather}
 holomorphic in $\mathbb{C}\times \mathbb{D}\big(u^0\big)$ and represented by a convergent matrix valued series
 \begin{gather*}
 V(z,u)=I+\sum_{k\colon k_1+\cdots +k_n>0} V_k z^{k_0}\big(u-u_1^0\big)^{k_1}\cdots \big(u-u_n^0\big)^{k_n}
 \end{gather*}
 (here $k=(k_0,k_1,\dots,k_n)$ and $V_k$ are matrices), such that
 \begin{gather} \label{31luglio2018-4}
 {\rm d}\widetilde{Y}=\big[ \omega_0\big(z,u^0\big){\rm d} z\big] \widetilde{Y} \equiv \left[ \left(\frac{A\big(u^0\big)}{z}+\Lambda\big(u^0\big)\right){\rm d} z\right] \widetilde{Y}.
 \end{gather}
 The above admits fundamental solutions in Levelt form
 \begin{gather} \label{31luglio2018-5}
 \widetilde{Y}^{(0)}(z)=W(z) z^D z^L,\qquad W(z)=W_0 +\sum_{\ell=1}^\infty W_\ell z^\ell, \qquad \det(W_0)\neq 0,
 \end{gather}
which are independent of $u$ ($u^0$ being fixed). Here, $W(z)$ converges and defines a holomorphic function on $\mathbb{C}$. This means that
 \begin{gather*}
 Y^{(0)}(z,u):=V(z,u)W(z) \widetilde{Y}^{(0)}(z)
 \end{gather*}
is a fundamental matrix solution of~\eqref{11marzo2018-2} in Levelt form, with constant exponents~$L$ and~$D$. Moreover, $V(z,u)W(z) $ is holomorphic on $\mathbb{C}\times \mathbb{D}\big(u^0\big)$ and its series representation can be rearranged as follows
 \begin{gather*}
 G(u) \left(I+\sum_{j=1}^\infty \Psi_j(u)z^j\right), \qquad G(u)= V(0,u)W_0.
 \end{gather*}
 Notice that $G(u)$ puts $A(u)$ in Jordan form. The proof above can be also deduced by directly applying Theorems~4 and~7 of~\cite{YT}.

\label{18marzo2018-2} For the sake of computations, we can write $L=\Sigma+N$, where $\Sigma=\Sigma_1\oplus \cdots \oplus \Sigma_\ell$ is diagonal, with $\Sigma_q=\sigma_q I_{\dim (\Sigma_q)}$ (here $I_{\dim (\Sigma_q)}$ stands for the identity matrix of dimension $\dim (\Sigma_q)$), while $N=N_1\oplus \cdots \oplus N_\ell$ is nilpotent. Since~$\Sigma_q$ and~$N_q$ have the same dimension ($q=1,\dots,\ell$), we have
 \begin{gather*}
 [\Sigma,N]=0,
 \end{gather*}
 and thus
 \begin{gather*}
 z^D z^L=z^D z^\Sigma z^N = z^{D+\Sigma} z^N =z^{D+\Sigma}\sum_{\ell=0}^{\overline{k}} \frac{N^\ell}{\ell!} (\log z)^\ell,
 \end{gather*}
 for some finite $\overline{k}$.

\label{16marzo2018-1}Consider a completely integrable linear Pfaffian system
\begin{gather}\label{29marzo2018-1}
{\rm d} Y=\omega Y,\qquad \omega=\left(\Lambda+\frac{A(u)}{z}\right){\rm d} z+\sum_{j=1}^n \omega_j(z,u) {\rm d} u_j,
\end{gather}
with $A(u)$ holomorphic on $\mathbb{D}\big(u^0\big)$ and $\omega_1(z,u), \dots,\omega_n(z,u)$ holomorphic on $ \mathbb{C}\times \mathbb{D}\big(u^0\big)$. Let $z=\infty$ be at most a pole of $\omega_1,\dots,\omega_n$. Then:
\begin{itemize}\itemsep=0pt
\item[$(A)$] each $\omega_j(z,u)$ is linear in $z$ and determined by $A(u)$ up to an arbitrary holomorphic diagonal matrix $\mathcal{D}_j(u)$ on $\mathbb{D}\big(u^0\big)$, with the following structure\footnote{Explicitly, \begin{gather*}\left(
 \frac{A_{ab}(\delta_{aj}-\delta_{bj})}{u_a-u_b}
 \right)_{a,b=1}^n
 =\left(
\begin{matrix}
0 & 0&\dfrac{ -A_{1j}}{u_1-u_j} & 0& 0
 \\
0 &0 &\vdots & 0& 0
 \\
 \dfrac{ A_{j1}}{u_j-u_1} & \cdots&0 & \cdots&\dfrac{ A_{jn}}{u_j-u_n}
 \\
0 &0 &\vdots &0 & 0
 \\
 0 &0 &\dfrac{ -A_{nj}}{u_n-u_j} & 0& 0
\end{matrix}
\right)
\end{gather*}
}
\begin{gather*}
\omega_j(z,u)= zE_j+\omega_j(0,u),\\
\omega_j(0,u):=\left( \frac{A_{ab}(u) (\delta_{aj}-\delta_{bj})}{u_a-u_b} \right)_{a,b=1}^n+ \mathcal{D}_j(u),
 \end{gather*}
 where $ \mathcal{D}_j(u)$ is obtained by differentiating a matrix $\mathcal{D}$ on $\mathbb{D}\big(u^0\big)$, whose diagonal entries only depend on~$u$:
 \begin{gather*}
 \mathcal{D}_j(u)=\frac{\partial \mathcal{D}(u)}{\partial u_j};
 \end{gather*}

 \item[$(B)$] $A(u)$ satisfies \eqref{23marzo2018-8}
 \begin{gather*}
 \frac{\partial A}{\partial u_j}=[\omega_j(0,u),A],\qquad j=1,\dots,n;
 \end{gather*}

 \item[$(C)$] the above non-linear system is Frobenius integrable;

 \item[$(D)$] the diagonal of $A$, namley the matrix $B=\operatorname{diag}(A_{11},\dots,A_{nn})$ in \eqref{11marzo2018-10-BIS}, is constant;

\item[$(E)$] given the relations \eqref{14marzo2018-4} for a fundamental matrix $Y(z,u)$ holomorphic on $\mathcal{R}\times \mathbb{D}\big(u^0\big)$, then each $H_r$ satisfies\footnote{We have
 $H_r(u)=\exp\{\operatorname{diag}({\mathcal{D}(u)})\} H_r^0$, with $H_r^0$ a constant invertible matrix.}
\begin{gather*}
\frac{\partial H_r}{\partial u_j}=\mathcal{D}_j(u)H_r\qquad \forall\, r\in\mathbb{Z};
\end{gather*}

\item[$(F)$] from $(E)$, it follows that $H_r(u)$ is holomorphic on $\mathbb{D}\big(u^0\big)$, and $Y_r(z,u)$ extends holomorphically on $\mathcal{R}\times \mathbb{D}\big(u^0\big)$.
\end{itemize}

In this paper, we have assumed that each $\omega_j(z,u)$ is holomorphic at $z=0$. More generally, one may study a Pfaffian system with Laurent expansions at $z=0$
 \begin{gather*}
 \omega_j(z,u)= \sum_{m=1}^{p_j}\frac{\omega_j^{(-m)}(u)}{z^m}+\sum_{m=0}^\infty \omega_j^{(m)}(u)z^m.
 \end{gather*}
 Here, we only remark that if $A(u)$ is non-resonant for each $u$ in the domain of interest (it means that the difference of two eigenvalues of~$A(u)$ cannot be a non-zero integer), then the Frobenius integrability conditions imply that $\omega_j(z,u)$ is holomorphic at $z=0$, namely
 \begin{gather*}
 \omega_j^{(-p_j)}(u)=\omega_j^{(-p_j+1)}(u)=\cdots =\omega_j^{(-1)}(u)=0.
 \end{gather*}
 To see this, substitute the Laurent expansion into~\eqref{24marzo2018-1}. We find the following recurrence relations:

From the negative powers of $z$:
\begin{gather}
 (A+p_j)\omega_j^{(-p_j)}-\omega_j^{(-p_j)}A=0; \label{eq(1)} \\
(A+m)\omega^{(-m)}-\omega^{(-m)}A=\big[\omega^{(-m-1)},\Lambda\big],\qquad \text{for $m= p_j-1,p_j-2,\dots,1$}; \label{eq(2)}\\
 \frac{\partial A}{\partial u_j}=\big[\omega^{(0)},A\big]+\big[\omega^{(-1)},\Lambda\big]. \label{eq(3)}
\end{gather}

 From the power $z^0$:
\begin{gather} A\omega_j^{(1)}-\omega_j^{(1)}A-\omega_j^{(1)}+E_j=\big[\omega_j^{(0)},\Lambda\big].\label{eq(4)}
\end{gather}

From the positive powers $z$:
\begin{gather}
(A-m-1)\omega_j^{(m+1)}-\omega_j^{(m+1)}A=\big[\omega_j^{(m)},\Lambda\big], \qquad m\geq 1 . \label{eq(5)}
 \end{gather}
 If $A$ is non-resonant, the Sylvester equation~\eqref{eq(1)} determines $\omega_j^{(-p_j)}=0$, thus the Sylvester equations~\eqref{eq(2)} yield $\omega_j^{(-m)}=0$, $ m= p_j-1,p_j-2,\dots,1$. Moreover, the equations~\eqref{eq(5)} determine~$\omega_j^{(m+1)}$ for $m\geq 1$ in terms of $\omega_j^{(1)}$. In particular, each $\omega_j^{(m+1)}=0 $ if $\omega_j^{(1)}$ is diagonal.

 Finally, we notice that, independently of the resonance properties of $A$, equation~\eqref{eq(4)} determines the off-diagonal entries of $\omega_j^{(0)}$ in terms of $\omega_j^{(1)}$, to be \begin{gather*}\big(\omega_j^{(0)}\big)_{ab}=(u_a-u_b)^{-1}\big(\big[\omega_j^{(1)},A\big]+\omega_j^{(1)}\big)_{ab}.\end{gather*} Moreover, the diagonal part of~\eqref{eq(4)} yields \begin{gather*}\big(\omega_j^{(1)}\big)_{aa}=\delta_{ja}-\sum_{b\neq a}\big(\big(\omega_j^{(1)}\big)_{ab}A_{ba}-A_{ab}\big(\omega_j^{(1)}\big)_{ba}\big).\end{gather*} Under the assumptions of Proposition~\ref{16marzo2018-1}, we find that $\omega_j^{(1)}=E_j$ and $\omega_j^{(m+1)}=0$ for $m\geq 1$.

\label{18marzo2018-3}Let $Y(z,u)$ be a weak isomonodromic family of fundamental matrix solutions of the Pfaffian system \eqref{11marzo2018-2}, or equivalenlty \eqref{29marzo2018-1}, with coefficients \eqref{29marzo2018-2}. We call \eqref{11marzo2018-1} a~strong isomonodromic family of differential systems, and~$Y(z,u)$ a~strong isomonodromic family of fundamental solutions over $\mathbb{D}\big(u^0\big)$, if for all $r\in \mathbb{Z}$ the connection matrices~$H_r$ in~\eqref{14marzo2018-4} are independent of~$u$, namely
\begin{gather*} {\rm d} H_r=0.
\end{gather*}

\label{18marzo2018-4}
The deformation is strongly isomonodromic if and only if the fundamental matrices $Y_r(z,u)$ of the differential system \eqref{11marzo2018-1} also satisfy the Pfaffian system~\eqref{29marzo2018-1}
\begin{gather*}
{\rm d} Y_r=\omega Y_r, \qquad \forall \, r\in\mathbb{Z},\end{gather*}
 being the coefficients
 \begin{gather}\label{18marzo2018-11}
 \omega_j(z,u)= zE_j+[F_1,E_j] \equiv zE_j+\left( \frac{A_{ab}(u)(\delta_{aj}-\delta_{bj})}{u_a-u_b} \right)_{a,b=1}^n.
\end{gather}

bvious. We have
\begin{gather*}
\omega ={\rm d} Y Y^{-1}={\rm d} Y_r Y_r^{-1}+ Y_r {\rm d} H_r H_r^{-1}Y_r^{-1}.
\end{gather*}
Therefore, $ {\rm d} Y_r Y_r^{-1}=\omega$ if and only if ${\rm d} H_r=0$. Since ${\rm d} H_r=0$, then $\mathcal{D}_j=0$ in Proposition~\ref{16marzo2018-1}, so that $\omega_j$ is~\eqref{18marzo2018-11}.

\label{18marzo2018-10} The matrices $\mathbb{S}_r$, $B$, $D$, $L$, $C_r$ ($r\in \mathbb{Z}$) are called the {\rm essential monodromy data} associated with the fundamental matrix solutions $Y_r(z,u)$ and $Y^{(0)}(z,u)$ of the system \eqref{11marzo2018-1}. In view of \eqref{18marzo2018-6} and \eqref{18marzo2018-7}, it suffices to consider the data
 \begin{gather*}
 \mathbb{S}_0, \ \mathbb{S}_1, \ B, \ D, \ L, \ C_0.
 \end{gather*}
 or equivalently, for some fixed value of $r$,
 \begin{gather*}
 \mathbb{S}_r, \ \mathbb{S}_{r+1}, \ B, \ D, \ L, \ C_r.
 \end{gather*}

\label{18marzo2018-9}A deformation is strongly isomonodromic as in Definition~{\rm \ref{18marzo2018-3}} if and only if
\begin{gather*}
{\rm d} \mathbb{S}_r={\rm d} \mathbb{S}_{r+1}=0, \qquad {\rm d} C_r=0,
\end{gather*}
for one value of $r\in\mathbb{Z}$.

or a weak isomonodromic deformation $D$, $L$ and $B$ are constant (Propositions~\ref{30luglio 2018-3} and~\ref{16marzo2018-1}), so we have nothing to prove about them.

$\bullet$ Suppose that the deformation is strong, so that ${\rm d} Y_r=\omega Y_r$ by Proposition~\ref{18marzo2018-4}. We prove that ${\rm d} C_r=0$ for any $r$. Indeed
\begin{align*}
\omega ={\rm d} Y_rY_r^{-1}&={\rm d} Y^{(0)} \big(Y^{(0)}\big)^{-1}+Y^{(0)} {\rm d} C_r C_r^{-1} \big(Y^{(0)}\big)^{-1}\\
& = \omega +Y^{(0)} {\rm d} C_r C_r^{-1} \big(Y^{(0)}\big)^{-1} \quad \Longleftrightarrow \quad {\rm d} C_r=0.
\end{align*}
We prove that ${\rm d} \mathbb{S}_r=0$. Invoking again Proposition~\ref{18marzo2018-4}, we have
\begin{gather*}
\omega_j= \frac{\partial Y_{r+1}}{\partial u_j} Y_{r+1}^{-1}=\frac{\partial Y_{r}}{\partial u_j} Y_{r}^{-1} +
 Y_{r}\frac{\partial \mathbb{S}_r}{\partial u_j} \mathbb{S}_r^{-1}Y_{r}^{-1}
 =\omega_j+ Y_{r}\frac{\partial \mathbb{S}_r}{\partial u_j} \mathbb{S}_r^{-1}Y_{r}^{-1}
 \quad \Longleftrightarrow \quad
\frac{\partial \mathbb{S}_r}{\partial u_j}=0.
\end{gather*}

$\bullet$ Conversely, we assume that ${\rm d} \mathbb{S}_0={\rm d} \mathbb{S}_1={\rm d} B={\rm d} C_0={\rm d} L=0$, and that $D$ is constant. First, we see that ${\rm d} \mathbb{S}_r=0$ and ${\rm d} C_r=0$ for any $r$, by formulae~\eqref{18marzo2018-6} and~\eqref{18marzo2018-7}. By virtue of Proposition \ref{18marzo2018-4}, it suffices to show that ${\rm d} Y_r=\omega Y_r$ for any~$r$. By construction $\partial_zY_r=\omega_0(z,u)Y_r$, which is the differential system~\eqref{11marzo2018-1}, so it suffices to show that $\partial_j Y_r=\omega_j Y_r$, $j=1,\dots,n$. Since ${\rm d} C_0=0$ and each ${\rm d} \mathbb{S}_r=0$, we have
\begin{gather}\label{2agosto2018-1}
{\rm d} Y^{(0)}\big(Y^{(0)}\big)^{-1} = {\rm d} Y_0 Y_0^{-1}=\cdots= {\rm d} Y_r Y_r^{-1}={\rm d} Y_{r+1}Y_{r+1}^{-1}=\cdots \qquad \forall\, r\in \mathbb{Z}.
\end{gather}
Moreover, $Y^{(0)}$ is a weak isomonodromic family, so that ${\rm d} Y^{(0)}=\omega Y^{(0)}$, where $\omega$ is \eqref{29marzo2018-1} with components \eqref{29marzo2018-2}, namely
\begin{gather*}
\omega_j(z,u)=zE_j+[F_1(u),E_j]+\mathcal{D}_j(u).
\end{gather*}
Thus, by \eqref{2agosto2018-1}, each $Y_r$ also satisfies
\begin{gather*}
{\rm d} Y_r= \omega Y_r,\qquad\forall\, r.
\end{gather*}
We need to prove that $\mathcal{D}_j(u)=0$. At $z=\infty$, using the fact that $dB=0$ and $\partial_j\Lambda=E_j$, we have for any $r\in \mathbb{Z}$
 \begin{gather*}
\omega_j=\frac{\partial Y_r}{\partial u_j}Y_r^{-1}=\frac{\partial \widehat{Y}_r}{\partial u_j}\widehat{Y}_r^{-1} +z\widehat{Y}_r E_j \widehat{Y}_r ^{-1}= zE_j +[F_1,E_j]+\mathcal{O}\big(z^{-1}\big).
\end{gather*}
The above $\mathcal{O}(z^{-1})$ stands for an asymptotic expansion in $\mathcal{S}_r(\overline{\mathbb{D}^\prime})$, given for any $r$ by the same series in $z^{-1}$. Since $ \omega_j$ is single valued in $z$, then $\mathcal{O}(z^{-1})$ is a convergent Taylor series at $z=\infty$. Thus, $\omega_j-zE_j-[F_1,E_j]$ is holomorphic both at $z=0$ and $z=\infty$, and it vanishes as $z\to \infty$. Hence, by Liouville theorem,
 \begin{gather*}
\omega_j =zE_j+[F_1,E_j],
 \end{gather*}
with $\mathcal{D}_j=0$. The equality extends from $\mathbb{D}^\prime$ to $\mathbb{D}\big(u^0\big)$ by analiticity.

\label{19marzo2018-5} Consider the Pfaffian system \eqref{11marzo2018-2}--\eqref{11marzo2018-6}, with $A(u)$ holomorphic on $\mathcal{U}_\epsilon\big(u^C\big)$. Let~$\mathbb{D}\big(u^0\big)$ be compactly contained in a $\widetilde{\tau}$-cell. Assume that the Frobenius integrability holds on~$\mathbb{D}\big(u^0\big)$ and that the $\omega_j(z,u)$ are holomorphic on $\mathbb{C}\times \mathbb{D}\big(u^0\big)$, with $z=\infty$ being at most a~pole, so that Proposition~{\rm \ref{16marzo2018-1}} holds on $\mathbb{D}\big(u^0\big)$ and \eqref{11marzo2018-2}--\eqref{11marzo2018-6} becomes system~\eqref{29marzo2018-1} with coefficients~\eqref{29marzo2018-2} on~$\mathbb{D}\big(u^0\big)$. Then, the following statements are true:
\begin{itemize}\itemsep=0pt
\item[$i)$] The coefficients $\omega_j(z,u)$ in~\eqref{29marzo2018-2} extend holomorphically on $\mathcal{U}_\epsilon\big(u^C\big)$ if and only if $\mathcal{D}_j(u)$ is holomorphic on $\mathcal{U}_\epsilon\big(u^C\big)$ and the following vanishing conditions hold in $\mathcal{U}_\epsilon\big(u^C\big)$:
\begin{gather}\label{22marzo2018-1}
A_{ij}(u)=\mathcal{O}(u_i-u_j)\qquad \text{whenever $u_i-u_j\to 0$ at a point of $\Delta$}.
\end{gather}
 In this case, the system \eqref{29marzo2018-1}, \eqref{29marzo2018-2} is Frobenius integrable on the whole $\mathcal{U}_\epsilon\big(u^C\big)$.

\item[$ii)$] A fundamental matrix solution $Y(z,u)$ exists holomorphic on $\mathcal{R}\times \mathcal{U}_\epsilon\big(u^C\big)$ if and only if~\eqref{22marzo2018-1} holds.
\end{itemize}

he statement follows simply by recalling that, by Proposition \ref{16marzo2018-1}, for $u\in\mathbb{D}\big(u^0\big)$ we have \eqref{29marzo2018-2}, namely
\begin{gather*}
 \omega_j(z,u)= zE_j+\left( \frac{A_{ab}(\delta_{aj}-\delta_{bj})}{u_a-u_b} \right)_{a,b=1}^n+\mathcal{D}_j(u),
\end{gather*}
so that if $u_i-u_j\to 0$, the condition $A_{ij}\to 0$ guarantees analyticity on $\mathcal{U}_\epsilon\big(u^C\big)$. The integrability condition \eqref{11marzo2018-3} then holds by analytic continuation from $\mathbb{D}\big(u^0\big)$ to $\mathcal{U}_\epsilon\big(u^C\big)$. The last statement concerning $Y(z,u)$ follows from the fact that if~\eqref{22marzo2018-1} holds, then the Pfaffian system is integrable and linear on $\mathcal{U}_\epsilon\big(u^C\big)$ with holomorphic (in $u$) coefficients. Conversely, if a fundamental matrix $Y(z,u)$ exists holomorphic on $\mathcal{R}\times \mathcal{U}_\epsilon\big(u^C\big)$, then $\omega={\rm d} YY^{-1}$ has coefficients holomorphic in $u$ on $\mathcal{U}_\epsilon\big(u^C\big)$, which implies~\eqref{22marzo2018-1}.

he coefficients $F_k(u)$ are computed recursively from \eqref{11marzo2018-1}. This standard computation yields coefficients depending rationally on $A(u)$ and on the differences $(u_i-u_j)$, which appear in the denominators, as in \eqref{5aprile2018-1}. In particular \eqref{18marzo2018-8} holds:
\begin{gather*}(F_1)_{ij}(u)=\frac{A_{ij}(u)}{u_j-u_i}, \qquad i\neq j, \qquad (F_1)_{ii}(u)=-\sum_{j\neq i}A_{ij}(u)(F_1)_{ji}(u).
\end{gather*}
Thus, if \eqref{22marzo2018-1} holds, $F_1(u)$ is holomorphic in $\mathcal{U}_{\epsilon}\big(u^C\big)$. By Proposition \ref{22marzo2018-1-BIS}, the asymptotic expansion is uniform in compact subsets of a cell, so we can substitute it into $\partial_iY=\omega_i Y$ (with~$\omega_i$ as in~\eqref{18marzo2018-11}), compare coefficients of $z^{-l}$ and find
\begin{gather}\label{21luglio-3}
[F_{l+1}(u),E_i]=[F_1(u),E_i]F_l(u)-\partial_i F_l(u),\qquad l\geq 1,
\end{gather}
with
\begin{gather*}
 [F_{l+1}(u),E_i ]=\left(
\begin{matrix}
0 & & (F_{l+1})_{1i} & & 0
\\
 & & \vdots & &
\\
-(F_{l+1})_{i1} & \cdots & 0 & \cdots & -(F_{l+1})_{in}
\\
 & & \vdots &
 \\
 0 & & (F_{l+1})_{ni} & & 0
\end{matrix}
\right).
\end{gather*}
Moreover, $\operatorname{diag}(F_{l+1})$ is determined by
\begin{gather}\label{3nov2015-6}
l (F_{l+1})_{ii}(u)=-\sum_{j\neq i}A_{ij}(u)(F_l)_{ji}(u).
\end{gather}
Therefore, \eqref{21luglio-3}--\eqref{3nov2015-6} recursively determines $F_{l+1}$ as a function of $F_l, F_{l-1}, \dots, F_1$. Since $F_1$ is holomorphic when conditions~\eqref{22marzo2018-1} hold, by induction all the $F_{l+1}(u)$ are holomorphic.

\label{23marzo2018-3} Consider the differential system \eqref{22marzo2018-6}, with coefficients $A(u)$, $A_j(u)$ holomorphic on $\mathcal{U}_\epsilon\big(u^C\big)$, where $\epsilon$ is specified as above. Assume that all the $F_k(u)$ are holomorphic on $\mathcal{U}_\epsilon\big(u^C\big)$. Moreover, assume that the fundamental matrices
 \begin{gather*}Y_r(z,u) =\widehat{Y}_r(z,u) z^{B(u)}e^{z\Lambda},
 \end{gather*}
 which are holomorphic on a $\widetilde{\tau}$-cell by Proposition~{\rm \ref{22marzo2018-1-BIS}}, admit analytic continuation on the who\-le~$\mathcal{U}_\epsilon\big(u^C\big)$ as single valued holomorphic functions of~$u$, for any $r\in \mathbb{Z}$ and $z$ fixed. Then the following results hold.

 \begin{itemize}\itemsep=0pt
 \item The asymptotic representation of $Y_r(z,u)$ in terms of the formal matrix
 \begin{gather*} Y_F(z,u)=F(z,u)z^{B(u)}e^{z\Lambda},\end{gather*} extends beyond the $\widetilde{\tau}$-cell, namely
\begin{gather*}
 \widehat{Y}_r(z,u)\sim F(z,u)= I+\sum_{k=1}^\infty F_k(u) z^{-k}, \qquad z\to \infty \text{ in } \widehat{\mathcal{S}}_r,
 \end{gather*}
 uniformly in every compact subset of $\mathcal{U}_{\epsilon_1}\big(u^C\big)$ for every $\epsilon_1<\epsilon$. Moreover, for any $r\in\mathbb{Z}$ the Stokes matrix $\mathbb{S}_r(u)$ relating $Y_r(z,u)$ and $Y_{r+1}(z,u)$ satisfies
 \begin{gather*}
 (\mathbb{S}_r)_{ij}=(\mathbb{S}_r)_{ji}=0 \qquad \text{for $i$, $j$ such that } u_i^C=u_j^C.
 \end{gather*}
 \item The system \eqref{22marzo2018-6} at {\rm fixed} $u=u^C$, namely
 \begin{gather} \label{29marzo2018-3}
 \frac{{\rm d} Y}{{\rm d} z}=\left(\Lambda\big(u^C\big) +\frac{A\big(u^C\big)}{z}+\sum_{j=2}^\infty \frac{A_j\big(u^C\big)}{z^j}\right) Y,
