 \begin{gather*}
 \mathring{Y}_F(z)=\mathring{F}(z) z^{B(u^C)}e^{z\Lambda(u^C)},
 \end{gather*}
 where $\mathring{F}(z)=I+ \sum\limits_{f=1}^\infty \mathring{F}_Kz^{-k} $ is a formal series and $ B\big(u^C\big)=\operatorname{diag}\big(A_{11}\big(u^C\big),\dots,A_{nn}\big(u^C\big)\big)$.

 \item The solution $\mathring{Y}_F(z)$ is unique if and only if the diagonal entries of $A\big(u^C\big)$ do not differ by non-zero integers; otherwise, there is a family of formal solutions $ \mathring{Y}_F(z)$.

 \item For any fixed formal solution $\mathring{Y}_F(z)$ of \eqref{29marzo2018-3}, there are unique actual solutions
 \begin{gather*}
 \mathring{Y}_r(z)=\mathring{\widehat{Y}}_r(z) z^{B(u^C)}e^{z\Lambda(u^C)},\qquad r\in \mathbb{Z},
