 \end{gather*}
Let $\mathring{\mathbb{S}}_r$ be the Stokes matrices of the above solutions $\mathring{Y}_r(z)$. Then,
 \begin{gather*}
 \lim_{u\to u_c} \mathbb{S}_r(u)=\mathring{\mathbb{S}}_r.
 \end{gather*}
\end{itemize}

\label{25marzo2018-1}
