oints a), b), c) follow from Propositions~\ref{23marzo2018-1} and~\ref{23marzo2018-2}, Theorem~\ref{23marzo2018-3} and Corollary~\ref{31luglio2018-1}. We only need to justify that given a fundamental matrix $ \mathring{Y}^{(0)}(z)$ of~\eqref{23marzo2018-6} in Levelt form~\eqref{31luglio2018-7}, there exists a fundamental matrix~$Y^{(0)}(z,u)$ of ${\rm d} Y=\omega(z,u) Y$ in Levelt form (namely an isomonodromic fundamental matrix of \eqref{11marzo2018-TRIS}), such that
 \begin{gather*}Y^{(0)}\big(z,u^C\big)=\mathring{Y}^{(0)}(z).\end{gather*}
To this end, recall the proof of Proposition \ref{30luglio 2018-3}, with the replacements $u\mapsto u^C$ and $\mathbb{D}\big(u^0\big) \mapsto \mathcal{U}_\epsilon\big(u^0\big)$ (this becomes the proof of Corollary \ref{31luglio2018-1}). The gauge transformation \eqref{31luglio2018-3}
\begin{gather*}
Y=V(z,u) \widetilde{Y},\qquad V\big(z,u^C\big)=I,
\end{gather*}
 transforms the Pfaffian system to a differential system \eqref{31luglio2018-4} in variable $z$ only, with $u^0$ replaced by $u^C$, namely
\begin{gather*}
 {\rm d}\widetilde{Y}= \left[ \left(\frac{A\big(u^C\big)}{z}+\Lambda\big(u^C\big)\right){\rm d} z\right] \widetilde{Y},\qquad {\rm d} \equiv \frac{\partial }{\partial z} {\rm d} z.
 \end{gather*}
 This is exactly \eqref{23marzo2018-6}. A fundamental solution $\mathring{Y}^{(0)}(z)$ in Levelt form \eqref{31luglio2018-7} is actually a solution~\eqref{31luglio2018-5}, namely
 \begin{gather*}
 \mathring{Y}^{(0)}(z)=W(z) z^D z^{\mathring{L}},\qquad W(z)=W_0 +\sum_{\ell=1}^\infty W_\ell z^\ell, \qquad \det(W_0)\neq 0.
 \end{gather*}
 Thus, we conclude from \eqref{31luglio2018-3} that
 \begin{gather*}
 Y^{(0)}(z,u)= V(z,u) \mathring{Y}^{(0)}(z), \qquad Y^{(0)}\big(z,u^C\big)= \mathring{Y}^{(0)}(z).
 \end{gather*}

 Point d) follows from the recursive computation of the coefficients $\mathring{F}_k$ in
 \begin{gather*}
 \mathring{Y}_F(z)=\left(I+ \sum_{k=1}^\infty \mathring{F}_kz^{-k} \right)z^{B(u^C)}e^{z \Lambda(u^C)}.
 \end{gather*}
 For $1\leq \ell \neq s \leq n$ such that $u_\ell^C=u_s^C$, one finds at step $k$ that (recall that $\operatorname{diag}(A(u))=B$ is constant)
 \begin{gather*}
 (A_{\ell\ell}-A_{ss}+k)(\mathring{F}_k)_{\ell s}= \text{known expression from previous steps}.
 \end{gather*}
 This implies that if $A_{\ell\ell}-A_{ss}+k$ is different from zero for every $k\geq 1$, then all the $\mathring{F}_k$ are uniquely recursively determined. For the detailed formulae of the recursion, see \cite[Section~4]{CDG}.

\label{28febbraio2018-1}
The $u$-family of Fuschsian systems \eqref{25febbraio2018-3} is weakly isomonodromic if and only if there exists a matrix valued $1$-form $\omega$, holomorphic on $ \mathcal{E}$, such that
\begin{itemize}\itemsep=0pt
\item[$1)$] for any fixed $u\in \mathbb{D}\big(u^0\big)$ we have
\begin{gather*}\omega|_{u} = \sum_{i=1}^N\frac{A_i(u)}{z-u_i} {\rm d} z;\end{gather*}
\item[$2)$] ${\rm d}\omega=\omega\wedge \omega$.
\end{itemize}

\label{26febbraio2018-3}Consider the Pfaffian system
\begin{gather}\label{26febbraio2018-2}
{\rm d} Y=\left(\sum_{i=1}^N\frac{A_i(u)}{z-u_i}{\rm d} (z-u_i)+\sum_{i=1}^n \gamma_i(u){\rm d} u_i\right)Y,
\end{gather}
where the matrices $A_i(u)$ and $\gamma_i(u)$ are holomorphic in $\mathbb{D}\big(u^0\big)$. Then each $A_i(u)$ is holomorphically similar to a constant Jordan form~$J_i$. Namely, there exists~$G_i(u)$ holomorphic in $\mathbb{D}\big(u^0\big)$ such that $J_i=G_i(u)^{-1}A_i(u)G_i(u)$ is Jordan and independent of~$u$. In particular, the spectrum of each $A_i(u)$ is independent of~$u$, so that a Schlesinger isomonodromic deformation is isospectral.

uppose we want to prove that $J_1=G_1(u)^{-1}A_1(u)G_1(u)$ is independent of $u$. As far as the local behaviour around $z-u_1=0$ is concerned, (\ref{26febbraio2018-2}) can be rewritten as
\begin{gather} \label{30luglio2018-1}
{\rm d} Y=\left(\frac{P_0(x,u)}{x}{\rm d} x+\sum_{i=1}^N P_i(x,u){\rm d} u_i\right) Y,
\end{gather}
where the $N+1$ independent variables are $ x:=z-u_1; u_1, u_2,\dots,u_N$. Each $P_k(x,u)$, for $k=0,1,\dots,N$, is holomorphic in a~neighbourhood of $x=z-u_1=0$. Explicitly
\begin{gather}
\frac{P_0}{x}= \frac{A_1(u)}{x}+\sum_{j=2}^N\frac{A_j(u)}{x-(u_j-u_1)},\nonumber\\
\sum_{i=1}^NP_i {\rm d} u_i= \sum_{j=2}^N\frac{A_j(u)}{x-(u_j-u_1)}({\rm d} u_1-{\rm d} u_j)+\sum_{j=1}^N\gamma_j(u){\rm d} u_j.\label{30luglio2018-2}
\end{gather}
 So, the proof repeats the arguments of the proofs of Lemma~\ref{24marzo2018-2} and Proposition~\ref{11marzo2018-7}.

e rewrite \eqref{28febbraio2018-5} as
\begin{gather*}
 Y(z,u)= \widehat{Y}_i(z,u) (z-u_i)^{D_i}C_i(u)(z-u_i)^{\mathcal{L}_i},\\
 \mathcal{L}_i:=C_i(u)^{-1}L_i(u)C_i(u)\equiv \frac{1}{2\pi i } \log M_i, \qquad 0\leq \operatorname{Re} (\text{Eigenvls of }\mathcal{L}_i)<1.
 \end{gather*}
 Since ${\rm d} M_i=0$, then ${\rm d}\mathcal{L}_i=0$. Hence, the eigenvalues $\sigma_q^{(i)}$ of $L_i(u)$ are constant. Now, the eigenvalues $\lambda_{q,s}^{(i)}(u)=\sigma_q^{(i)}+d_{q,s}^{(i)}$ of $A_i(u)$ are continuous, being $A_i(u)$ continuous, so the integers~$d_{q,s}^{(i)}$ are constant.

e prove that $L_1$ and $C_1$ are constant, being the other cases analogous. The Pfaffian system is rewritten in the form \eqref{30luglio2018-1}--\eqref{30luglio2018-2}. Then, by \cite[Theorem~5]{YT}, there exists a gauge transformation
\begin{gather*}
Y=V(x,u)\widetilde{Y},
\end{gather*}
holomorphic in a neighbourhood of $(x,u)=(0,u^0)$, given by a convergent series
\begin{gather*}
V(x,u)=I+\sum_{k_1+\cdots +k_N>0} V_k x^{k_0}\big(u_1-u_1^0\big)^{k_1}\cdots\big(u_N-u_N^0\big)^{k_N} ,
\end{gather*}
with $k=(k_0,k_1,\dots,k_N)$, such that the Pfaffian system is transformed to
\begin{gather*}
{\rm d} \widetilde{Y}=
\left(\frac{P_0(0,u^0)}{x}{\rm d} x\right) \widetilde{Y} \equiv \left[ \left(\frac{A_1\big(u^0\big)}{x}+\sum_{j=2}^N\frac{A_j\big(u^0\big)}{x-\big(u_j^0-u_1^0\big)}\right) {\rm d} x\right] \widetilde{Y}.
\end{gather*}
Thus, $\widetilde{Y}$ satisfies an $n\times n$ Fuchsian system in variable $x$, independent of parameters (being $u^0$ fixed), so that there is a fundamental matrix solutions in Levelt form at $x=0$, independent of~$u$,
\begin{gather*}
\widetilde{Y}_1(x):=W(x) x^{D_1} x^{L_1} ,\qquad W(x) = W_0+\sum_{\ell=1}^\infty W_\ell x^\ell,
\end{gather*}
the series being convergent and holomorphic at $x=0$. Hence, there is a fundamental matrix solution of the initial system of the form
\begin{gather*}
Y_1(z,u) =V(x,u) W(x) x^{D_1} x^{L_1} \equiv \widehat{Y}_1(z,u) (z-u_1)^{D_1}(z-u_1)^{L_1},
\end{gather*}
where
\begin{gather*}
\widehat{Y}_1(z,u):= V(x,u) W(x) |_{x=z-u_1}\\
= \left(I+\sum_{k_1+\cdots +k_N>0} V_k (z-u_1)^{k_0}\big(u_1-u_1^0\big)^{k_1}\cdots\big(u_N-u_N^0\big)^{k_N}\right) \left(W_0+\sum_{\ell=1}^\infty W_\ell (z-u_1)^\ell\right).
\end{gather*}
The latter can be rewritten as a convergent saries at $z=u_1$ with coefficients holomorphic in $u$:
\begin{gather*}
\widehat{Y}_1(z,u)=G_1(u) \left(I+\sum_{\ell=1}^\infty \Psi_\ell(u)(z-u_1)^\ell\right),\qquad G_1(u)=V(0,u)W_0.
\end{gather*}
Notice that $G_1(u)$ puts $A_1(u)$ in Jordan form as in Proposition~\ref{26febbraio2018-3}. The proof is concluded observing that $Y_1(z,u)$ solves the initial Pfaffian system, so that also $Y(z,u)=Y_1(z,u)C_1$ is a~fundamental solution if and only if $C_1$ is constant. The proof can also be deduced directly from \cite[Theorems~4 and~7]{YT}.

\label{26marzo2018-5}The {\rm essential monodromy data} associated with a weakly isomonodromic $Y(z{,}u)$ are the matrices
\begin{gather*}
D_j, \ L_j, \ C_j,\qquad j=1,\dots,N.
\end{gather*}

Recall that the $D_j$ are always constant for a weak isomonodromic deformation (Lemma~\ref{29marzo2018-4}). Moreover, \begin{gather*}{\rm d} C_j=0 \quad \text{implies} \quad {\rm d} L_j=0,
\end{gather*}
because we can write the monodromy matrices as $M_j=C_j^{-1}e^{2\pi i L_j}C_j$. Thus, one can define a~strong deformation to be one such that all the matrices $C_j$ are constant, in the same way as in Definition \ref{18marzo2018-3} (the connection matrices $C_j$ play the same role of the matrices $H_r$).

\label{25marzo2018-7}
All the possible matrix differential $1$-form of Theorem~{\rm \ref{28febbraio2018-1}}, holomorphic on $\mathbb{P}^1 \times \mathbb{D}\big(u^0\big)\backslash \bigcup_{i=1}^n \{z-u_i=0\}$, which give an isomonodromic family of Fuchsian systems \eqref{25febbraio2018-3}, have the form
\begin{gather}\label{1marzo2018-1}
\omega =\omega_s +\sum_{i=1}^N \gamma_i(u) {\rm d} u_i + \sum_{i=1}^N\sum_{j=1}^N\sum_{k=1}^{m_i} \frac{ \gamma_{ijk}(u)}{(z-u_i)^k}{\rm d} u_j.
\end{gather}
where $\gamma_i(u)$, $\gamma_{ijk}(u)$ are holomorphic on $\mathbb{D}\big(u^0\big)$ and $m_i $ is the maximal integer difference of eigenvalues of~$A_i(u)$.

he proof is in \cite{Bolibruch} and \cite{Bolibruch1}. We take the Schlesinger deformation $\omega_s$ with the same initial condition $A_i^0=A_i\big(u^0\big)$ of $\omega$, namely
\begin{gather*}
\omega_s|_{u^0}=\omega|_{u^0}.
\end{gather*}
Let $Y_s(z,u)$ be an isomonodromic fundamental matrix for $\omega_s$. By isomonodromicity, $Y(z,u)$ and $Y_s(z,u)$ have the same monodromy matrices, which are those of
\begin{gather*}\frac{{\rm d} Y}{{\rm d} z}=\sum\limits_{i=1}^N\frac{A_i^0}{z-u_i^0} Y.
\end{gather*}
Hence, $\Gamma(z,u):=Y(z,u) Y_s(z,u)^{-1}$ is single valued and meromorphic on $\mathbb{P}^1\times \mathbb{D}\big(u^0\big)$, with poles at $z=u_i$, $1\leq i \leq N$. Moreover $\omega = {\rm d}\Gamma \Gamma^{-1} +\Gamma\omega_s \Gamma^{-1}$. This expression does show that $\omega$ has the structure~(\ref{1marzo2018-1}). In order to predict~$m_i$, we write
\begin{align*}
&Y(z,u)=\widehat{Y}_i(z,u) (z-u_i)^{D_i}(z-u_i)^{L_i(u)}C_i(u),
\\
&
Y_s(z,u)=\widehat{Y}_i^s(z,u) (z-u_i)^{D_i}(z-u_i)^{L_i^s}C_i^s,
\end{align*}
where $L_i^s$ and $C_i^s$ are constant, by Proposition \ref{28febbraio2018-6}. Being the monodromy $M_i$ of $Y$ and $Y_s$ the same, we have
\begin{gather*}
C_i(u)^{-1}L_i(u)C_i(u)={C_i^s}^{-1}L_i^sC_i^s.
\end{gather*}
 Thus,
 \begin{gather*}
 L_i(u)=\mathcal{R}_i L_i^s \mathcal{R}_i^{-1},
 \qquad
 \mathcal{R}_i:= C_i(u){C_i^s}^{-1},
 \end{gather*}
 and $\mathcal{R}_i$ must have the same block structure of $L_i(u)$ and $L_i^s$. Moreover,
 \begin{gather*}
 Y(z,u)=\widehat{Y}_i(z,u)(z-u_i)^{D_i} \mathcal{R}_i (z-u_i)^{L_i^s}C_i^s.
 \end{gather*}
 Thus, we have
\begin{gather*}
{\rm d} Y Y^{-1} = {\rm d}\widehat{Y}_i \widehat{Y}_i^{-1} +\widehat{Y}_i \left(\frac{D_i+(z-u_i)^{D_i}\mathcal{R}_i E_i^s \mathcal{R}_i^{-1}(z-u_i)^{-D_i}}{z-u_i}\right) \widehat{Y}_i^{-1} {\rm d}(z-u_i)\\
\hphantom{{\rm d} Y Y^{-1} =}{} +\widehat{Y}_i(z-u_i)^{D_i}{\rm d}\mathcal{R}_i \mathcal{R}_i^{-1} (z-u_i)^{-D_i} \widehat{Y}_i^{-1}\\
\hphantom{{\rm d} Y Y^{-1}}{} = {\rm d}\widehat{Y}_i \widehat{Y}_i^{-1} +\widehat{Y}_i\left(\frac{D_i+(z-u_i)^{D_i}L_i(u) (z-u_i)^{-D_i}}{z-u_i}\right)\widehat{Y}_i^{-1}{\rm d}(z-u_i)\\
\hphantom{{\rm d} Y Y^{-1} =}{} +\widehat{Y}_i(z-u_i)^{D_i}{\rm d} \mathcal{R}_i \mathcal{R}_i^{-1} (z-u_i)^{-D_i} \widehat{Y}_i^{-1}\\
\hphantom{{\rm d} Y Y^{-1}}{} = \text{holomorphic}+ \frac{A_i(u)}{z-u_i} {\rm d}(z-u_i) +\widehat{Y}_i (z-u_i)^{D_i}{\rm d}\mathcal{R}_i \mathcal{R}_i^{-1} (z-u_i)^{-D_i} \widehat{Y}_i^{-1}.
\end{gather*}
The last term $\widehat{Y}_i (z{-}u_i)^{D_i}{\rm d}\mathcal{R}_i \mathcal{R}_i^{-1} (z{-}u_i)^{-D_i} \widehat{Y}_i^{-1}$ contains matrix entries with poles at \smash{$(z{-}u_i){=}0$}, plus holomorphic terms. This proves again, by Liouville theorem, that $\omega$ has the struc\-tu\-re~(\ref{1marzo2018-1}). The block diagonal structure of $\mathcal{R}_i$, being the same as that of $D_i=D_1^{(i)}\oplus \cdots \oplus D_{\ell_i}^{(i)}$, assures that $m_i$ is the maximum over $q$ of the maximal difference of the eigenvalues of $D_q^{(i)}$, $q=1,2,\dots,\ell_i$. This is precisely the maximal integer difference of eigenvalues of $A_i(u)$.

If for every $i=1,\dots,N$ the matrices $A_i$ are non-resonant, then every $\omega$ of Theorem~{\rm \ref{28febbraio2018-1}}, defining an isomonodromic family of Fuchsian systems~\eqref{25febbraio2018-3}, is of the form
 \begin{gather*}
 \omega=\omega_s+\sum_{i=1}^n \gamma_i(u){\rm d} u_i.
 \end{gather*}

\label{16marzo2018-2} Let $\omega_0(x)=\big(\Lambda+\frac{A}{z}\big)$ be as in~\eqref{11marzo2018-6}, let $\omega_1,\dots,\omega_n$ be holomorphic of $(z,u)\in \mathbb{C}\times \mathbb{D}\big(u^0\big)$, and~$A(u)$ holomorphic on $\mathbb{D}\big(u^0\big)$. Assume that $z=\infty$ is at most a pole of $\omega_1,\dots,\omega_n$. Then, for $u\in \mathbb{D}^\prime$, the Pfaffian system has the following structure
\begin{gather*}
\omega=\left(\Lambda+\frac{A}{z}\right){\rm d} z +\sum_{j=1}^n ( zE_j+\omega_j(0,u)) {\rm d} u_j ,
 \end{gather*}
 with
\begin{gather*}                       
 \omega_j(0,u)=[F_1(u),E_j]+\mathcal{D}_j(u),
\end{gather*}
 where $F_1$, appearing in the formal expansion \eqref{14marzo2018-1}, is given explicitly in \eqref{18marzo2018-8}, and
\begin{gather*}
 \mathcal{D}_j(u)=\frac{\partial H_r(u)}{\partial u_j}H_r(u)^{-1}
\end{gather*}
 is a diagonal matrix independent of $r\in\mathbb{Z}$ and holomorphic on $u\in \mathbb{D}^\prime$. Moreover,
 \begin{gather*}{\rm d} B=0. \end{gather*}

e write
\begin{gather*}
\omega ={\rm d} Y Y^{-1}.
\end{gather*}
where $Y(z,u)=Y^{(0)}(z,u) H$ is a holomorphic isomonodromic family. Recalling that $D$ is constant and ${\rm d} L={\rm d} H=0$ (one can take directly $H=I$), we have
\begin{gather*}
\omega_j=\frac{\partial Y}{\partial u_j} Y^{-1} =\frac{\partial \widehat{Y}^{(0)}}{\partial u_j} \big(\widehat{Y}^{(0)}\big)^{-1}= \operatorname{holom}(z,u),
 \end{gather*}
where $\operatorname{holom}(z,u)$ is some convergent Taylor series at $z=0$, of order $\mathcal{O}(1)$ for $z\to 0$, with holomorphic coefficients depending on $u\in\mathbb{D}\big(u^0\big)$. Keeping into account the explicit form \eqref{3aprile2018-1} of $\widehat{Y}^{(0)}$ (in particular, recall that $G(u)$ satisfies \eqref{23marzo2018-7} as in Proposition \ref{11marzo2018-7}), we have
\begin{gather}
\label{14marzo2018-8}
\omega_j=\partial_jG G^{-1}+\mathcal{O}(z) \equiv \omega_j(0,u)+\mathcal{O}(z).
\end{gather}

Successively, we compute the representation of $\omega_j$ close to $z=\infty$, using \eqref{14marzo2018-4},
\begin{align*}
\omega_j&=\frac{\partial Y}{\partial u_j} Y^{-1}\\
&=\frac{\partial \widehat{Y}_r}{\partial u_j} \widehat{Y}_r^{-1}+\widehat{Y}_r\frac{\partial B}{\partial u_j} \widehat{Y}_r^{-1} \log z + z\widehat{Y}_rE_j\widehat{Y}_r^{-1}
+\widehat{Y}_rz^B\left(e^{z\Lambda}\frac{\partial H_r}{\partial u_j}H_r^{-1} e^{-z\Lambda}\right)z^{-B}\widehat{Y}_r^{-1}.
\end{align*}
We recall that $u_i\neq u_j$ for $i\neq j$ and observe that $e^{(u_i-u_j)z}$ diverges for $z\to\infty$ in some subsector of $\mathcal{S}_r(\overline{ \mathbb{D}^\prime})$, because the central angular opening is more than~$\pi$. Hence
\begin{gather*}
e^{z\Lambda}\frac{\partial H_r}{\partial u_j}H_r^{-1} e^{-z\Lambda} \quad\text{does not diverge exponentially}
\quad \Longleftrightarrow \quad \frac{\partial H_r}{\partial u_j}H_r^{-1} \quad \text{is diagonal}.\end{gather*}
 Since $\Lambda$ and $B$ are also diagonal, we have
\begin{gather*}
\omega_j=\left(\frac{\partial \widehat{Y}_r}{\partial u_j} \widehat{Y}_r^{-1}+z\widehat{Y}_r E_j \widehat{Y}_r^{-1}+\widehat{Y}_r\frac{\partial H_r}{\partial u_j}H_r^{-1} \widehat{Y}_r^{-1}\right)
+\widehat{Y}_r\frac{\partial B}{\partial u_j} \widehat{Y}_r^{-1} \log z.
\end{gather*}
We have at most a pole at $z=\infty$ if and only if
\begin{gather*}
\frac{\partial B}{\partial u_j}=0.
\end{gather*}
Then, the asymptotic behaviour \eqref{14marzo2018-1} of $\widehat{Y}_r$ implies that
\begin{gather*}
\omega_j=z\widehat{Y}_r E_j \widehat{Y}_r^{-1}
+\widehat{Y}_r\frac{\partial H_r}{\partial u_j}H_r^{-1} \widehat{Y}_r^{-1}
+\frac{\partial \widehat{Y}_r}{\partial u_j} \widehat{Y}_r^{-1}=
zE_j+[F_1,E_j]+\frac{\partial H_r}{\partial u_j}H_r^{-1}+\mathcal{O}\left(\frac{1}{z}\right)
\end{gather*}
in the sector $\mathcal{S}_r(\overline{ \mathbb{D}^\prime})$. The asymptotics holds for every $r\in\mathbb{Z}$. Now, the asymptotic expansion of a function (in our case $\omega_j$) on a sector is unique. Since $\mathcal{S}_r(\overline{ \mathbb{D}^\prime})\cap \mathcal{S}_{r+1} (\overline{\mathbb{D}^\prime})$ is not empty, this implies that $\omega_j$ has the same expansion in every sector $\mathcal{S}_r(\overline{ \mathbb{D}^\prime})$, $\forall\, r$. In particular, $\partial_jH_r H_r^{-1}$ cannot depend on $r$. We set
\begin{gather*}
 \mathcal{D}_j(u):=\frac{\partial H_r(u)}{\partial u_j}H_r^{-1}(u) \qquad \forall\, r\in\mathbb{Z}.
 \end{gather*}
Moreover, being $\omega_j$ single valued, the asymptotic series represented by $\mathcal{O}\big(\frac{1}{z}\big)$ above, must be a~convergent Taylor expansion. In conclusion
\begin{gather*}
\omega_j-(zE_j+[F_1,E_j]+\mathcal{D}_j)=\mathcal{O}\left(\frac{1}{z}\right) \qquad \text{is holomorphic at $z=\infty$}.
\end{gather*}
Keeping into account \eqref{14marzo2018-8} and Liouville theorem, we obtain that
\begin{gather*}
\omega_j-(zE_j+[F_1,E_j]+\mathcal{D}_j)=0,
\end{gather*}
as we wanted to prove.

\label{16marzo2018-3}Consider a Pfaffian system ${\rm d} Y=\omega Y$, and assume that $\omega$ has the following structure
\begin{gather*}\omega=\left(\Lambda+\frac{A(u)}{z}\right){\rm d} z+\sum_{j=1}^n ( zE_j+\omega_j(0,u) ){\rm d} u_j,
\end{gather*}
 where $A(u)$ and $\omega_1(0,u),\dots,\omega_n(0,u)$ are holomorphic on $\mathbb{D}\big(u^0\big)$. Then, the Frobenius integrability conditions \eqref{11marzo2018-3} are equivalent to $1)$ and $2)$ below:
 \begin{itemize}\itemsep=0pt
 \item[$1)$] $\omega_j(0,u)$ satisfies the constraint
 \begin{gather} \label{15marzo2018-1}
 [\Lambda,\omega_j(0,u)]=[E_j,A];
 \end{gather}
 \item[$2)$] $A(u)$ satisfies the non-linear system
\begin{gather} \label{15marzo2018-2}
\frac{\partial A}{\partial u_j}=[\omega_j(0,u),A],\qquad j=1,2,\dots,n,
 \end{gather}
which is Frobenius integrable.
\end{itemize}
The above \eqref{15marzo2018-1} determines $\omega_j(0,u)$ up to a diagonal matrix $\mathcal{D}_j(u)$, as follows
\begin{gather}\label{15marzo2018-3}
\omega_j(0,u)=\left( \frac{A_{ab}(u)(\delta_{aj}-\delta_{bj})}{u_a-u_b} \right)_{a,b=1}^n+\mathcal{D}_j(u).
\end{gather}
Moreover, the diagonal matrix $B:=\operatorname{diag}(A_{11},\dots,A_{nn})$ is constant and
 \begin{gather*}
 \mathcal{D}_j=\frac{\partial \mathcal{D}}{\partial u_j},
 \end{gather*}
 where $\mathcal{D}$ is a matrix whose diagonal only depends on $u\in \mathbb{D}\big(u^0\big)$.

or brevity, let us write $\omega_j(0)$ in place of $\omega_j(0,u)$. As in the proof of Lemma \ref{24marzo2018-2}, consider \eqref{11marzo2018-3} for $\beta=0$, $\alpha=j=1,\dots,n$:
\begin{gather*}
\frac{\partial}{\partial u_j}\left(\Lambda+\frac{A}{z}\right)+\left(\Lambda+\frac{A}{z}\right)(zE_j+\omega_j(0))=
\frac{\partial}{\partial z}(zE_j+\omega_j(0))+(zE_j+\omega_j(0))\left(\Lambda+\frac{A}{z}\right).
\end{gather*}
Since $\partial_j\Lambda=E_j$, we have
\begin{gather*}
\cancel{E_j}+\frac{\partial_jA}{z}+\cancel{z\Lambda E_j}+\Lambda\omega_j(0)+AE_j+\frac{A\omega_j(0)}{z}=\cancel{E_j}+\cancel{zE_j\Lambda} +E_jA+\omega_j(0)\Lambda+\frac{\omega_j(0)A}{z}.
\end{gather*}
The above identity is equivalent to \eqref{15marzo2018-1} and \eqref{15marzo2018-2}. Consider now \eqref{11marzo2018-3} for $\alpha=k$, $\beta=j\in\{1,\dots,n\}$:
\begin{gather*}
\frac{\partial}{\partial u_k}(zE_j+\omega_j(0))+(zE_j+\omega_j(0))(zE_k+\omega_k(0))\\
\qquad{} =\frac{\partial}{\partial u_j}(zE_k+\omega_k(0))+(zE_k+\omega_k(0))(zE_j+\omega_j(0)),
\end{gather*}
so that
\begin{gather*}
\frac{\partial \omega_j(0)}{\partial u_k}+\cancel{z^2E_jE_k}+z(E_j\omega_k(0)+\omega_j(0)E_k)+\omega_j(0)\omega_k(0)\\
\qquad{} =\frac{\partial \omega_k(0)}{\partial u_j}+\cancel{z^2E_kE_j}+z(E_k\omega_j(0)+\omega_k(0)E_j)+\omega_k(0)\omega_j(0).
\end{gather*}
Identifying the coefficients of the same powers of $z$ we get
\begin{gather}\label{26marzo2018-1}
[E_j,\omega_k(0)]=[E_k,\omega_j(0)],\\
\label{15marzo2018-8}
\frac{\partial \omega_j(0)}{\partial u_k}+\omega_j(0)\omega_k(0)=\frac{\partial \omega_k(0)}{\partial u_j}+\omega_k(0)\omega_j(0),\qquad 1\leq j\neq k \leq n.
\end{gather}
\eqref{15marzo2018-8} is the Frobenius integrability condition of system \eqref{15marzo2018-2}, as it is shown in the proof of Lemma~\ref{24marzo2018-2}. Explicitly writing \eqref{15marzo2018-1}, a simple calculation yields \eqref{15marzo2018-3}. Now, \eqref{26marzo2018-1} is identically satisfied. Substitution of \eqref{15marzo2018-3} into \eqref{15marzo2018-8} shows, by considering the diagonal, that
\begin{gather*}
\frac{\partial \mathcal{D}_j}{\partial u_k}-\frac{\partial \mathcal{D}_k}{\partial u_j}=0, \qquad j\neq k,
\end{gather*}
so that the matrix valued form $\sum\limits_{j=1}^n\mathcal{D}_j(u) {\rm d} u_j$ is closed. Being the domain simply connected, it is also exact. Substitution of \eqref{15marzo2018-3} into \eqref{15marzo2018-2} and direct calculation shows that
\begin{gather*}
\frac{\partial A_{kk}}{\partial u_1}=\cdots=\frac{\partial A_{kk}}{\partial u_n}=0,\qquad \forall\, k=1,\dots,n.\tag*{}
\end{gather*}\renewcommand{}{}

he assumption that $\omega_j(z,u)$ has at most a pole at $z=\infty$ implies that Lemma~\ref{16marzo2018-2} applies for $u\in \mathbb{D}^\prime$. Hence
\begin{gather}\label{17marzo2018-1}
\omega_j(z,u)=zE_j+[F_1(u),A(u)]+ \mathcal{D}_j(u) \qquad \text{for $u\in \mathbb{D}^\prime$}.
